# (table, constraint, rule): {symbols} and {assets} are the coin lists of each side, {usdt} the assets with USDT,
# {caps} the risk caps. Each rule is the one the earlier migration wrote, with the list in place of its literal.
SYMBOL_CHECKS = (
    ("market_observations", "market_symbol", "symbol IN {symbols}"),
    ("market_feed_state", "market_feed_symbol", "symbol IN {symbols}"),
    ("market_incidents", "market_incident_symbol", "symbol IS NULL OR symbol IN {symbols}"),
    ("market_candle_confirmations", "market_candle_confirmations_symbol_check", "symbol IN {symbols}"),
    ("execution_incidents", "execution_incidents_symbol_check", "symbol IS NULL OR symbol IN {symbols}"),
    ("strategy_evaluations", "strategy_evaluations_symbol_check", "symbol IN {symbols}"),
    ("position_mandates", "position_mandates_symbol_check", "symbol IN {symbols}"),
    ("positions", "positions_symbol_check", "symbol IN {symbols}"),
    ("orders", "orders_symbol_check", "symbol IN {symbols}"),
    ("fills", "fills_symbol_check", "symbol IN {symbols}"),
    ("evaluation_marks", "evaluation_marks_symbol_check", "symbol IN {symbols}"),
    ("decision_intents", "decision_intents_symbol_check", "symbol IN {symbols}"),
    ("decision_position_terms", "decision_position_terms_symbol_check", "symbol IN {symbols}"),
)
ASSET_CHECKS = (
    ("journal_postings", "journal_account_asset",
     "(book_account NOT IN ('OWNER_CASH','VIRTUAL_CAPITAL') OR asset = 'USDT') "
     "AND (book_account <> 'OWNER_ASSET' OR asset IN {assets})"),
    ("journal_postings", "journal_asset", "asset IN {usdt}"),
    ("reservations", "reservation_valid", "asset IN {usdt} AND amount > 0"),
    ("account_holdings", "account_holdings_asset_check", "asset IN {assets}"),
    ("orders", "orders_reserved_asset_check", "reserved_asset IN {usdt}"),
    ("fills", "fills_fee_asset_check", "fee_asset IN {usdt}"),
    ("risk_breach_events", "risk_breach_events_cap_check", "cap IN {caps}"),
)

# Every table above, in the order the running app takes them: an engine step locks the account's holdings first, then
# reads positions and orders and the market; the market worker writes an observation before its feed row.
LOCK_ORDER = ("account_holdings", "positions", "position_mandates", "orders", "fills", "journal_postings",
              "reservations", "risk_breach_events", "strategy_evaluations", "evaluation_marks", "execution_incidents",
              "decision_intents", "decision_position_terms", "market_observations", "market_feed_state",
              "market_incidents", "market_candle_confirmations")
if set(LOCK_ORDER) != {table for table, _name, _rule in (*SYMBOL_CHECKS, *ASSET_CHECKS)}:
    raise RuntimeError("0016's lock order must name every table whose check it changes")

